          const data: { customers: QuoteCustomer[] } = await response.json()
          if (!cancelled) {
            const found = data.customers?.find((c) => c.id === selectedCustomerId)
            setSelectedCustomerCache(found ?? null)
          }
        }
      } catch {
        // Silently fail
      }
    }

    fetchSelectedCustomer()
    return () => { cancelled = true }
  }, [selectedCustomerId])

